def request_edit(request, pk):
    hr_request = get_object_or_404(HRRequest, pk=pk)
    if not can_change_hr_request(request.user, hr_request):
        raise PermissionDenied("You cannot edit this request.")
    form = HRRequestForm(request.POST or None, instance=hr_request, user=request.user, limited_status=not is_hr_admin(request.user))
    if request.method == "POST" and form.is_valid():
        updated = form.save(commit=False)
        if not is_hr_admin(request.user):
            updated.assigned_to = hr_request.assigned_to
            updated.status = hr_request.status
        updated.save()

